import{_ as d,o as a,c as e,a2 as s}from"./chunks/framework.B4hAkGey.js";const c=JSON.parse('{"title":"8.1 基础入门：WebRTC 直播 vs 传统 RTMP","description":"","frontmatter":{},"headers":[],"relativePath":"guide/08-live-streaming/basics.md","filePath":"guide/08-live-streaming/basics.md","lastUpdated":1792683941000}'),r={name:"guide/08-live-streaming/basics.md"};function n(o,t,i,h,l,p){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_8-1-基础入门-webrtc-直播-vs-传统-rtmp" tabindex="-1">8.1 基础入门：WebRTC 直播 vs 传统 RTMP <a class="header-anchor" href="#_8-1-基础入门-webrtc-直播-vs-传统-rtmp" aria-label="Permalink to &quot;8.1 基础入门：WebRTC 直播 vs 传统 RTMP&quot;">​</a></h1><blockquote><p>为什么 WebRTC 直播正在吃掉传统 RTMP 直播的份额？两者架构、延迟、成本的对比。</p></blockquote><hr><h2 id="_8-1-1-四种直播技术对比" tabindex="-1">8.1.1 四种直播技术对比 <a class="header-anchor" href="#_8-1-1-四种直播技术对比" aria-label="Permalink to &quot;8.1.1 四种直播技术对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>RTMP 推流 + HLS 拉流</th><th>WebRTC 直播</th><th>WebRTC → SFU → CDN 转推</th><th>ZOOM / Teams</th></tr></thead><tbody><tr><td>延迟</td><td>2~5 秒</td><td><strong>&lt; 300ms</strong></td><td>300ms~3s（可调）</td><td>100~200ms</td></tr><tr><td>并发能力</td><td>10w+（CDN 优势）</td><td>数千（SFU 瓶颈）</td><td>10w+（CDN 兜底）</td><td>数千</td></tr><tr><td>互动能力</td><td>❌ 观众不能上麦</td><td>✅ 观众随时连麦</td><td>✅ 互动 + 大规模分发</td><td>✅</td></tr><tr><td>架构复杂度</td><td>中</td><td>高（SFU 必装）</td><td>最高</td><td>闭源 SaaS</td></tr><tr><td>技术栈</td><td>ffmpeg + CDN</td><td>WebRTC + SFU</td><td>WebRTC + SFU + ffmpeg + CDN</td><td>闭源</td></tr><tr><td>成本</td><td>低</td><td>中~高</td><td>高</td><td>SaaS 订阅</td></tr></tbody></table><hr><h2 id="_8-1-2-主流直播架构" tabindex="-1">8.1.2 主流直播架构 <a class="header-anchor" href="#_8-1-2-主流直播架构" aria-label="Permalink to &quot;8.1.2 主流直播架构&quot;">​</a></h2><h3 id="架构-1-传统-rtmp-直播-纯观看" tabindex="-1">架构 1：传统 RTMP 直播（纯观看） <a class="header-anchor" href="#架构-1-传统-rtmp-直播-纯观看" aria-label="Permalink to &quot;架构 1：传统 RTMP 直播（纯观看）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主播 → RTMP 推流 → 媒体服务器 → CDN → 观众（HLS 拉流）</span></span>
<span class="line"><span>                                            ↑</span></span>
<span class="line"><span>                                    延迟 2~5 秒，但分发成本极低</span></span>
<span class="line"><span>                                    单 CDN 可支撑百万并发</span></span></code></pre></div><h3 id="架构-2-webrtc-sfu-互动" tabindex="-1">架构 2：WebRTC + SFU（互动） <a class="header-anchor" href="#架构-2-webrtc-sfu-互动" aria-label="Permalink to &quot;架构 2：WebRTC + SFU（互动）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主播 ──► SFU ──► 连麦观众 A</span></span>
<span class="line"><span>      │   │</span></span>
<span class="line"><span>      │   └──► 连麦观众 B</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      └──► 纯观看观众 C（SFU 直接分发）</span></span></code></pre></div><p><strong>SFU = Selective Forwarding Unit</strong>——只转发必要的流，不混音。</p><h3 id="架构-3-webrtc-→-sfu-→-rtmp-转推-互动-大规模" tabindex="-1">架构 3：WebRTC → SFU → RTMP 转推（互动 + 大规模） <a class="header-anchor" href="#架构-3-webrtc-→-sfu-→-rtmp-转推-互动-大规模" aria-label="Permalink to &quot;架构 3：WebRTC → SFU → RTMP 转推（互动 + 大规模）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主播 ──► SFU ──► 连麦观众（WebRTC 低延迟）</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      └──► SFU 输出一路合成流 → ffmpeg 转 RTMP → CDN → 百万观众（HLS）</span></span></code></pre></div><p><strong>这是现在电商直播的主流架构</strong>——主播和连麦观众走 WebRTC 低延迟互动，几十万纯观看观众走 CDN HLS。</p><hr><h2 id="_8-1-3-sfu-vs-mcu" tabindex="-1">8.1.3 SFU vs MCU <a class="header-anchor" href="#_8-1-3-sfu-vs-mcu" aria-label="Permalink to &quot;8.1.3 SFU vs MCU&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>SFU（选择性转发）</th><th>MCU（多点控制单元）</th></tr></thead><tbody><tr><td>工作方式</td><td>只转发原始流，不处理</td><td>把多路混音合成一路再发</td></tr><tr><td>延迟</td><td>最低（&lt; 50ms 额外）</td><td>较高（混编耗 CPU）</td></tr><tr><td>服务端 CPU</td><td>低</td><td>高（每路流要解码→合成→编码）</td></tr><tr><td>终端要求</td><td>高（每个观众收多路）</td><td>低（只收一路）</td></tr><tr><td>适用场景</td><td>WebRTC 原生</td><td>传统视频会议</td></tr><tr><td>主流开源</td><td><strong>Mediasoup / Janus / LiveKit / pion/ion</strong></td><td>Jitsi Videobridge（转 SFU 了）</td></tr></tbody></table><p><strong>现代 WebRTC 直播全用 SFU，不用 MCU。</strong></p><hr><h2 id="_8-1-4-主流开源-sfu-对比" tabindex="-1">8.1.4 主流开源 SFU 对比 <a class="header-anchor" href="#_8-1-4-主流开源-sfu-对比" aria-label="Permalink to &quot;8.1.4 主流开源 SFU 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SFU</th><th>语言</th><th>协议</th><th>规模</th><th>特点</th></tr></thead><tbody><tr><td><strong>Mediasoup</strong></td><td>C++ + Node API</td><td>WebRTC</td><td>5k~10k 并发/节点</td><td>业界最成熟，Mediasoup-client 强大</td></tr><tr><td><strong>Janus</strong></td><td>C</td><td>WebRTC + SIP</td><td>5k 并发/节点</td><td>插件架构，支持多种协议</td></tr><tr><td><strong>LiveKit</strong></td><td>Go</td><td>WebRTC</td><td>10k+ 并发/节点</td><td>Cloud 托管、协议完整、SDK 好</td></tr><tr><td><strong>pion/ion</strong></td><td>Go</td><td>WebRTC</td><td>5k 并发/节点</td><td>云原生，Kubernetes 友好</td></tr><tr><td><strong>mediasoup-demo</strong></td><td>Node</td><td>WebRTC</td><td>500 并发</td><td>教学 Demo</td></tr></tbody></table><hr><h2 id="_8-1-5-小结" tabindex="-1">8.1.5 小结 <a class="header-anchor" href="#_8-1-5-小结" aria-label="Permalink to &quot;8.1.5 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你应该记住</th><th></th></tr></thead><tbody><tr><td><strong>纯观看</strong> → RTMP + CDN</td><td>成本最低、并发最大</td></tr><tr><td><strong>需要互动</strong> → WebRTC + SFU</td><td>延迟 &lt; 300ms、观众可连麦</td></tr><tr><td><strong>互动 + 大规模</strong> → WebRTC + SFU + RTMP 转推</td><td>电商直播主流</td></tr><tr><td><strong>不用 MCU</strong></td><td>现代 WebRTC 直播全用 SFU</td></tr><tr><td><strong>入门推荐 Mediasoup 或 LiveKit</strong></td><td>文档全、生态好</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">8.2 进阶应用：SFU 架构与转码</a></p>`,28)])])}const u=d(r,[["render",n]]);export{c as __pageData,u as default};
